1	/****************************************************************************
2	 * apps/examples/fbraw/fbraw.c
3	 *
4	 * Raw framebuffer test - bypass LVGL, direct memory write
5	 * Tests if the display corruption is in driver or LVGL layer
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <fcntl.h>
13	#include <sys/ioctl.h>
14	#include <sys/mman.h>
15	#include <nuttx/video/fb.h>
16	#include <nuttx/cache.h>
17	#include <unistd.h>
18	
19	#define BORDER_W 30
20	
21	int main(int argc, FAR char *argv[])
22	{
23	    int fd;
24	    struct fb_videoinfo_s vinfo;
25	    struct fb_planeinfo_s pinfo;
26	    uint32_t *fb;
27	
28	    printf("\n=== RAW FRAMEBUFFER TEST ===\n");
29	
30	    fd = open("/dev/fb0", O_RDWR);
31	    if (fd < 0) {
32	        fprintf(stderr, "ERROR: Cannot open /dev/fb0\n");
33	        return 1;
34	    }
35	
36	    if (ioctl(fd, FBIOGET_VIDEOINFO, &vinfo) < 0) {
37	        fprintf(stderr, "ERROR: FBIOGET_VIDEOINFO failed\n");
38	        close(fd);
39	        return 1;
40	    }
41	
42	    if (ioctl(fd, FBIOGET_PLANEINFO, &pinfo) < 0) {
43	        fprintf(stderr, "ERROR: FBIOGET_PLANEINFO failed\n");
44	        close(fd);
45	        return 1;
46	    }
47	
48	    printf("VideoInfo: %u x %u, bpp=%u, stride=%u\n",
49	           vinfo.xres, vinfo.yres, pinfo.bpp, pinfo.stride);
50	
51	    fb = (uint32_t *)mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
52	                          MAP_SHARED | MAP_FILE, fd, 0);
53	    if (fb == MAP_FAILED) {
54	        fprintf(stderr, "ERROR: mmap failed\n");
55	        close(fd);
56	        return 1;
57	    }
58	
59	    uint32_t w = vinfo.xres;     /* 1080 */
60	    uint32_t h = vinfo.yres;     /* 2160 */
61	    uint32_t sp = pinfo.stride / 4; /* 1088 stride in pixels */
62	
63	    printf("W=%u H=%u Stride=%u bytes\n", w, h, pinfo.stride);
64	
65	    /* 清屏：全蓝 */
66	    for (uint32_t y = 0; y < h; y++)
67	        for (uint32_t x = 0; x < sp; x++)
68	            fb[y * sp + x] = 0xFF0000FF; /* 蓝色 ARGB */
69	
70	    /* 上边框30px：全红 */
71	    for (uint32_t y = 0; y < BORDER_W; y++)
72	        for (uint32_t x = 0; x < sp; x++)
73	            fb[y * sp + x] = 0xFFFF0000;
74	
75	    /* 下边框30px：全红 */
76	    for (uint32_t y = h - BORDER_W; y < h; y++)
77	        for (uint32_t x = 0; x < sp; x++)
78	            fb[y * sp + x] = 0xFFFF0000;
79	
80	    /* 中间一条横线：y=1080 处，10px高，绿色 */
81	    for (uint32_t y = h / 2 - 5; y < h / 2 + 5; y++)
82	        for (uint32_t x = 0; x < sp; x++)
83	            fb[y * sp + x] = 0xFF00FF00;
84	
85	    /* Flush cache */
86	    up_clean_dcache((uintptr_t)fb, (uintptr_t)fb + pinfo.fblen);
87	
88	    printf("=== TEST: Blue bg + Red top/bottom + Green center line ===\n");
89	    printf("If you see: blue background, red top/bottom borders,\n");
90	    printf("green line at EXACT center -> driver is correct\n\n");
91	
92	    while (1) sleep(1);
93	
94	    munmap(fb, pinfo.fblen);
95	    close(fd);
96	    return 0;
97	}
