332	/****************************************************************************
333	 * Name: up_fbinitialize
334	 *
335	 * Description:
336	 *   Initialize the framebuffer video hardware associated with the display.
337	 *
338	 * Input Parameters:
339	 *   display - In the case of hardware with multiple displays, this
340	 *     specifies the display.  Normally this is zero.
341	 *
342	 * Returned Value:
343	 *   Zero is returned on success; a negated errno value is returned on any
344	 *   failure.
345	 *
346	 ****************************************************************************/
347	
348	
349	int up_fbinitialize(int display)
350	{
351		int ret = -1;
352		// 获取旋转角度
353		s32 rotation_degree = 0;
354		disp_sys_script_get_item("disp", "degree0", &rotation_degree, 1);
355		disp_probe();
356		if ((g_disp_drv.disp_init.fb_width[display] == 0)
357			|| (g_disp_drv.disp_init.fb_height[display] == 0)) {
358	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
359			g_videoinfo.xres =
360				bsp_disp_get_screen_height_from_output_type
361				(display,
362				g_disp_drv.disp_init.output_type[display],
363				g_disp_drv.disp_init.output_mode[display]);
364			g_videoinfo.yres =
365				bsp_disp_get_screen_width_from_output_type
366				(display,
367				g_disp_drv.disp_init.output_type[display],
368				g_disp_drv.disp_init.output_mode[display]);
369	
370	#else
371			g_videoinfo.xres =
372				bsp_disp_get_screen_width_from_output_type
373				(display,
374				g_disp_drv.disp_init.output_type[display],
375				g_disp_drv.disp_init.output_mode[display]);
376			g_videoinfo.yres =
377				bsp_disp_get_screen_height_from_output_type
378				(display,
379				g_disp_drv.disp_init.output_type[display],
380				g_disp_drv.disp_init.output_mode[display]);
381	#endif
382		} else {
383	// 只有90/270度才交换宽高
384	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
385		if (rotation_degree == 1 || rotation_degree == 3) { // 90或270度
386			g_videoinfo.xres = g_disp_drv.disp_init.fb_height[display];
387			g_videoinfo.yres = g_disp_drv.disp_init.fb_width[display];
388		} else { // 0或180度不交换
389			g_videoinfo.xres = g_disp_drv.disp_init.fb_width[display];
390			g_videoinfo.yres = g_disp_drv.disp_init.fb_height[display];
391		}
392	#else
393			g_videoinfo.xres = g_disp_drv.disp_init.fb_width[display];
394			g_videoinfo.yres = g_disp_drv.disp_init.fb_height[display];
395	#endif
396		}
397		g_videoinfo.fmt = FB_FMT_RGB32;
398		g_videoinfo.nplanes = 1;
399	#ifdef CONFIG_FB_OVERLAY
400		g_videoinfo.noverlays = 1;
401	#endif
402		g_planeinfo.bpp = 32;
403		g_planeinfo.display = 0;
404		/* Force stride 64-byte alignment for Allwinner DE2.0 DMA */
405		g_planeinfo.stride = (g_videoinfo.xres * g_planeinfo.bpp / 8 + 63) & ~63;
406		g_planeinfo.fblen = g_planeinfo.stride * g_videoinfo.yres * FB_NUM;
407	
408		/* Ensure 64-byte alignment for LVGL */
409		uintptr_t map_vaddr = (uintptr_t)R528_DISP_DDR_MAPVADDR;
410		if (map_vaddr % 64 != 0)
411		{
412			lcdwarn("Warning: R528_DISP_DDR_MAPVADDR not 64-byte aligned: 0x%lx\\n", map_vaddr);
413			map_vaddr = (map_vaddr + 63) & ~63;
414		}
415		g_planeinfo.fbmem = (void *)map_vaddr;
416	
417		DEBUGASSERT(g_planeinfo.fbmem != NULL);
418		/* xres_virtual must match actual stride (including padding) */
419		g_planeinfo.xres_virtual = g_planeinfo.stride / (g_planeinfo.bpp / 8);
420		g_planeinfo.yres_virtual = g_videoinfo.yres * FB_NUM;
421		g_planeinfo.display = display;
422		memset(g_planeinfo.fbmem, 0, g_planeinfo.fblen);
423	
424		struct disp_layer_config config;
425		memset(&config, 0, sizeof(struct disp_layer_config));
426		config.channel = 1;
427		config.layer_id = 0;
428		config.enable = 1;
429	#if defined(CONFIG_SUNXI_DISP2_FB_HW_ROTATION_SUPPORT)
430	if (rotation_degree == 1 || rotation_degree == 3) { // 90或270度才交换
431	    config.info.screen_win.width = g_videoinfo.yres;   // 600
432	    config.info.screen_win.height = g_videoinfo.xres;  // 1024
433	} else { // 0或180度不交换
434	    config.info.screen_win.width = g_videoinfo.xres;   // 1024
435	    config.info.screen_win.height = g_videoinfo.yres;  // 600
436	}
437	#else
438	    config.info.screen_win.width = g_videoinfo.xres;   // 1024
439	    config.info.screen_win.height = g_videoinfo.yres;  // 600
440	#endif
441		config.info.mode = LAYER_MODE_BUFFER;
442		config.info.zorder = 1;
443		config.info.alpha_mode = 0;
444		config.info.alpha_value = 0xff;
445		config.info.fb.crop.x = (0LL) << 32;
446		config.info.fb.crop.y = ((long long)g_planeinfo.yoffset) << 32;
447		/* Use intermediate 64-bit variable to avoid 32-bit overflow */
448		{
449			long long crop_w = (long long)(g_planeinfo.stride / (g_planeinfo.bpp / 8));
450			long long crop_h = (long long)g_videoinfo.yres;
451			config.info.fb.crop.width = crop_w << 32;
452			config.info.fb.crop.height = crop_h << 32;
453		}
454		config.info.screen_win.x = 0;
455		config.info.screen_win.y = 0;
456	
457		config.info.fb.addr[0] =
458		    (unsigned long long)(unsigned int)g_planeinfo.fbmem;
459		config.info.fb.addr[1] = 0;
460		config.info.fb.addr[2] = 0;
461		config.info.fb.flags = DISP_BF_NORMAL;
462		config.info.fb.scan = DISP_SCAN_PROGRESSIVE;
463		/* Tell DE engine the real memory stride (1088 pixels = 4352 bytes) */
464		config.info.fb.size[0].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
465		config.info.fb.size[0].height = g_planeinfo.yres_virtual;
466		config.info.fb.size[1].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
467		config.info.fb.size[1].height = g_planeinfo.yres_virtual;
468		config.info.fb.size[2].width = g_planeinfo.stride / (g_planeinfo.bpp / 8);
469		config.info.fb.size[2].height = g_planeinfo.yres_virtual;
