3	 *
4	 * Tianma 1080x2160 MIPI DSI panel driver for R528
5	 * Based on RK3566 DTSI timing parameters
6	 ****************************************************************************/
7	
8	#include "tianma.h"
9	
10	static void lcd_power_on(u32 sel);
11	static void lcd_power_off(u32 sel);
12	static void lcd_bl_open(u32 sel);
13	static void lcd_bl_close(u32 sel);
14	static void lcd_panel_init(u32 sel);
15	static void lcd_panel_exit(u32 sel);
16	
17	#define panel_reset(sel, val) sunxi_lcd_gpio_set_value(sel, 0, val)
18	
19	static void lcd_cfg_panel_info(struct panel_extend_para *info)
20	{
21		/* No gamma/cmap mapping needed for this panel */
22		memset(info, 0, sizeof(struct panel_extend_para));
23	}
24	
25	static s32 lcd_open_flow(u32 sel)
26	{
27		LCD_OPEN_FUNC(sel, lcd_power_on, 20);
28		LCD_OPEN_FUNC(sel, lcd_panel_init, 50);
29		LCD_OPEN_FUNC(sel, sunxi_lcd_tcon_enable, 30);
30		LCD_OPEN_FUNC(sel, lcd_bl_open, 0);
31		return 0;
32	}
33	
34	static s32 lcd_close_flow(u32 sel)
35	{
36		LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
37		LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
38		LCD_CLOSE_FUNC(sel, lcd_panel_exit, 100);
39		LCD_CLOSE_FUNC(sel, lcd_power_off, 200);
40		return 0;
41	}
42	
43	static void lcd_power_on(u32 sel)
44	{
45		/* Power sequence matching RK3566 DTSI */
46		sunxi_lcd_power_enable(sel, 0);      /* IOVDD 1.8V */
47		sunxi_lcd_delay_ms(10);
48		sunxi_lcd_power_enable(sel, 1);      /* Core 1.8V */
49		sunxi_lcd_delay_ms(10);
50	
51		sunxi_lcd_pin_cfg(sel, 1);           /* MIPI pin config */
52		sunxi_lcd_delay_ms(20);
53	
54		/* Hardware reset: low pulse */
55		panel_reset(sel, 0);
56		sunxi_lcd_delay_ms(20);
57		panel_reset(sel, 1);
58		sunxi_lcd_delay_ms(120);             /* reset delay */
59	
60		sunxi_lcd_power_enable(sel, 2);      /* AVDD 3.3V */
61		sunxi_lcd_delay_ms(20);
62	}
63	
64	static void lcd_power_off(u32 sel)
65	{
66		sunxi_lcd_pin_cfg(sel, 0);
67		sunxi_lcd_delay_ms(10);
68		panel_reset(sel, 0);
69		sunxi_lcd_delay_ms(10);
70		sunxi_lcd_power_disable(sel, 2);
71		sunxi_lcd_power_disable(sel, 1);
72		sunxi_lcd_power_disable(sel, 0);
73	}
74	
75	static void lcd_bl_open(u32 sel)
76	{
77		sunxi_lcd_pwm_enable(sel);
78		sunxi_lcd_backlight_enable(sel);
79	}
80	
81	static void lcd_bl_close(u32 sel)
82	{
83		sunxi_lcd_backlight_disable(sel);
84		sunxi_lcd_pwm_disable(sel);
85	}
86	
87	static void lcd_panel_init(u32 sel)
88	{
89		/* Enable DSI clock before sending commands */
90		sunxi_lcd_dsi_clk_enable(sel);
91		sunxi_lcd_delay_ms(20);
92	
93		/* Panel init sequence from RK3566 DTSI */
94		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
95		sunxi_lcd_delay_ms(120);
96	
97		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
98		sunxi_lcd_delay_ms(20);
99	}
100	
101	static void lcd_panel_exit(u32 sel)
102	{
103		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF);
104		sunxi_lcd_delay_ms(20);
105		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE);
106		sunxi_lcd_delay_ms(80);
107	}
108	
109	static s32 lcd_user_defined_func(u32 sel, u32 para1, u32 para2, u32 para3)
110	{
111		return 0;
112	}
