/****************************************************************************
 * apps/examples/fbraw/fbraw.c
 *
 * Raw framebuffer diagnostic test — draws numbered color bands
 * to find exact Y cutoff point.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <nuttx/video/fb.h>
#include <nuttx/cache.h>
#include <unistd.h>

/* 8 distinct colors for banding */
static const uint32_t COLORS[] = {
    0xFFFF0000, /* Red    */
    0xFF00FF00, /* Green  */
    0xFF0000FF, /* Blue   */
    0xFFFFFF00, /* Yellow */
    0xFFFF00FF, /* Magenta*/
    0xFF00FFFF, /* Cyan   */
    0xFFFF8000, /* Orange */
    0xFF8000FF, /* Purple */
};
#define N_COLORS 8
#define BAND_H   30  /* each band 30px tall */

int main(int argc, FAR char *argv[])
{
    int fd;
    struct fb_videoinfo_s vinfo;
    struct fb_planeinfo_s pinfo;
    uint32_t *fb;

    printf("\n=== FBRAW STRIPE DIAGNOSTIC ===\n");

    fd = open("/dev/fb0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "ERROR: Cannot open /dev/fb0\n");
        return 1;
    }

    if (ioctl(fd, FBIOGET_VIDEOINFO, &vinfo) < 0) {
        fprintf(stderr, "ERROR: FBIOGET_VIDEOINFO failed\n");
        close(fd);
        return 1;
    }

    if (ioctl(fd, FBIOGET_PLANEINFO, &pinfo) < 0) {
        fprintf(stderr, "ERROR: FBIOGET_PLANEINFO failed\n");
        close(fd);
        return 1;
    }

    uint32_t w     = vinfo.xres;
    uint32_t h     = vinfo.yres;
    uint32_t sp    = pinfo.stride / 4; /* stride in pixels */
    uint32_t total_bands = h / BAND_H;

    printf("VideoInfo: %u x %u, stride=%u bytes, stride_px=%u\n",
           w, h, pinfo.stride, sp);
    printf("Total bands: %u (each %upx tall)\n", total_bands, BAND_H);
    printf("Drawing color bands from top to bottom...\n");

    /* Fill with alternating color bands */
    for (uint32_t y = 0; y < h; y++) {
        uint32_t band = y / BAND_H;           /* which band */
        uint32_t color = COLORS[band % N_COLORS];

        for (uint32_t x = 0; x < sp; x++) {
            fb[y * sp + x] = color;
        }
    }

    /* Draw white horizontal lines at band boundaries for easy counting */
    for (uint32_t b = 0; b <= total_bands; b++) {
        uint32_t line_y = b * BAND_H;
        if (line_y >= h) break;
        /* 2px white line at each boundary */
        for (uint32_t dy = 0; dy < 2 && (line_y + dy) < h; dy++) {
            for (uint32_t x = 0; x < sp; x++) {
                fb[(line_y + dy) * sp + x] = 0xFFFFFFFF;
            }
        }
    }

    /* Draw thick white border (full perimeter, 4px) */
    for (uint32_t y = 0; y < 4; y++) {
        for (uint32_t x = 0; x < sp; x++) {
            fb[y * sp + x] = 0xFFFFFFFF;                    /* top */
            fb[(h - 1 - y) * sp + x] = 0xFFFFFFFF;          /* bottom */
        }
    }
    for (uint32_t y = 0; y < h; y++) {
        for (uint32_t x = 0; x < 4; x++) {
            fb[y * sp + x] = 0xFFFFFFFF;                    /* left */
            fb[y * sp + w - 1 - x] = 0xFFFFFFFF;            /* right */
        }
    }

    /* Flush cache */
    up_clean_dcache((uintptr_t)fb, (uintptr_t)fb + pinfo.fblen);

    printf("=== DONE ===\n");
    printf("EXPECTED: %u color bands (Red,Green,Blue,Yellow,Magenta,Cyan,Orange,Purple,repeat)\n",
           total_bands);
    printf("          separated by white lines, with white border on all 4 sides.\n");
    printf("Count bands from top. Report the LAST visible band number and color.\n");
    printf("If bottom white border is visible, screen is fully working.\n\n");

    while (1) sleep(1);

    munmap(fb, pinfo.fblen);
    close(fd);
    return 0;
}

