/****************************************************************************
 * apps/examples/fbraw/fbraw.c
 *
 * Minimal raw framebuffer diagnostic — find Y cutoff point
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <nuttx/video/fb.h>
#include <nuttx/cache.h>
#include <unistd.h>

int main(int argc, FAR char *argv[])
{
    int fd;
    struct fb_videoinfo_s vinfo;
    struct fb_planeinfo_s pinfo;
    uint32_t *fb;
    uint32_t w, h, sp;
    uint32_t x, y;
    int color_idx = 0;

    fd = open("/dev/fb0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "ERR: open fb0\n");
        return 1;
    }

    ioctl(fd, FBIOGET_VIDEOINFO, &vinfo);
    ioctl(fd, FBIOGET_PLANEINFO, &pinfo);

    fb = (uint32_t *)mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
                          MAP_SHARED | MAP_FILE, fd, 0);
    if (fb == MAP_FAILED) {
        fprintf(stderr, "ERR: mmap\n");
        close(fd);
        return 1;
    }

    w  = vinfo.xres;
    h  = vinfo.yres;
    sp = pinfo.stride / 4;

    /* Print info using minimal printf */
    printf("FB %ux%u stride=%u\n", w, h, sp);

    /* Pattern: alternating 32-pixel stripes, 8 colors cycling */
    for (y = 0; y < h; y++) {
        /* Avoid division: use a counter */
        if ((y & 0x1F) == 0) {
            color_idx = ((y >> 5) & 0x7);
        }
        uint32_t color;
        switch (color_idx) {
            case 0: color = 0xFFFF0000; break; /* Red */
            case 1: color = 0xFF00FF00; break; /* Green */
            case 2: color = 0xFF0000FF; break; /* Blue */
            case 3: color = 0xFFFFFF00; break; /* Yellow */
            case 4: color = 0xFFFF00FF; break; /* Magenta */
            case 5: color = 0xFF00FFFF; break; /* Cyan */
            case 6: color = 0xFFFF8000; break; /* Orange */
            case 7: color = 0xFF8000FF; break; /* Purple */
            default: color = 0xFF000000; break;
        }
        for (x = 0; x < sp; x++) {
            fb[y * sp + x] = color;
        }
    }

    /* White line every 32 pixels for counting */
    for (y = 0; y < h; y += 32) {
        for (x = 0; x < sp; x++) {
            fb[y * sp + x] = 0xFFFFFFFF;
        }
    }

    /* White border, all 4 sides */
    for (y = 0; y < h; y++) {
        fb[y * sp + 0]     = 0xFFFFFFFF; /* left */
        fb[y * sp + w - 1] = 0xFFFFFFFF; /* right */
    }
    for (x = 0; x < sp; x++) {
        fb[0 * sp + x]       = 0xFFFFFFFF; /* top */
        fb[(h-1) * sp + x]   = 0xFFFFFFFF; /* bottom */
    }

    up_clean_dcache((uintptr_t)fb, (uintptr_t)fb + pinfo.fblen);

    puts("OK\n");
    while (1) sleep(1);
    return 0;
}
